import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { NOTE_NAMES, type StringTuning } from '../types';
import { getGuitarLook, onGuitarLookChange, type GuitarLook } from './guitarLook';

export interface ScaleNeckPosition {
  stringIndex: number;
  fret: number;
  label: string;
  role: 'root' | 'tone' | 'blue' | 'outside';
  active: boolean;
  target?: boolean;
}

export interface NeckState {
  frets: (number | null)[];
  tuning: StringTuning[];
  stringLabels?: string[];
  liveMidi: number | null;
  root: string | null;
  /** Explicit positions keep scale filters, degree labels and exact plucks in sync with 2D. */
  scalePositions?: ScaleNeckPosition[] | null;
  /** Optional positions to play next, drawn as dashed ghosts; panes that omit it render as before. */
  upcoming?: { stringIndex: number; fret: number; label: string }[] | null;
}

/**
 * An on-demand scene: no animation loop competes with microphone analysis.
 * Subclasses may extend the scene; everything except `world` mirroring is opt-in, so default panes render as before.
 */
export class Fretboard3D {
  protected renderer: THREE.WebGLRenderer;
  protected scene = new THREE.Scene();
  /** Holds the instrument, markers and lights so left-handed mode can mirror them together. */
  protected world = new THREE.Group();
  protected camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
  protected controls: OrbitControls;
  private observer: ResizeObserver;
  protected geometries = new Set<THREE.BufferGeometry>();
  protected materials = new Set<THREE.Material>();
  protected textures = new Map<string, THREE.CanvasTexture>();
  protected markers = new THREE.Group();
  protected targets: THREE.Object3D[] = [];
  protected raycaster = new THREE.Raycaster();
  protected abort = new AbortController();
  protected visible = true;
  protected disposed = false;
  protected frame = 0;
  private start = { x: 0, y: 0 };
  private pointers = new Set<number>();
  private gesture = false;
  protected home = new THREE.Vector3(0.7, 10.8, 9.3);
  /** -1 when the left-handed look mirrors the world. */
  protected mirror = 1;

  constructor(
    protected host: HTMLElement,
    protected onPick: (string: number, fret: number) => void,
    onUnavailable: () => void,
    descriptionId?: string,
  ) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'low-power' });
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 1.75));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.setClearColor(0x000000, 0);
    const canvas = this.renderer.domElement;
    canvas.setAttribute('aria-label', 'Interactive 3D guitar neck. Drag to orbit; click a string to play. Use 2D view for individual keyboard-accessible frets.');
    if (descriptionId) canvas.setAttribute('aria-describedby', descriptionId);
    canvas.tabIndex = 0;
    host.append(canvas);
    this.camera.position.copy(this.home);
    this.controls = new OrbitControls(this.camera, canvas);
    this.controls.enablePan = false;
    this.controls.enableDamping = false;
    this.controls.enableZoom = false; // Explicit zoom buttons leave page scrolling intact.
    this.controls.minPolarAngle = 0.12;
    this.controls.maxPolarAngle = Math.PI * 0.46;
    this.controls.minAzimuthAngle = -0.65;
    this.controls.maxAzimuthAngle = 0.65;
    this.controls.addEventListener('change', this.requestRender);
    this.controls.update();
    this.scene.add(this.world);
    this.world.add(new THREE.HemisphereLight(0xfff1d9, 0x4f3930, 3));
    const key = new THREE.DirectionalLight(0xffead5, 3.2);
    key.position.set(-3, 10, 5);
    this.world.add(key);
    const rim = new THREE.DirectionalLight(0xd3e5f2, 2);
    rim.position.set(4, 4, -5);
    this.world.add(rim);
    this.buildScene();
    this.world.add(this.markers);
    this.applyLook(getGuitarLook());
    onGuitarLookChange(look => this.applyLook(look), this.abort.signal);
    const options = { signal: this.abort.signal };
    canvas.addEventListener('pointerdown', e => {
      this.pointers.add(e.pointerId);
      if (this.pointers.size === 1) {
        this.start = { x: e.clientX, y: e.clientY };
        this.gesture = false;
      } else this.gesture = true;
    }, options);
    canvas.addEventListener('pointerup', e => {
      this.pointers.delete(e.pointerId);
      if (this.gesture || e.button !== 0 || Math.hypot(e.clientX - this.start.x, e.clientY - this.start.y) > 6) return;
      if (!this.setPickRay(e.clientX, e.clientY)) return;
      const hit = this.raycaster.intersectObjects(this.targets, false)[0];
      if (hit) this.onPick(hit.object.userData.string, hit.object.userData.fret);
    }, options);
    canvas.addEventListener('pointercancel', e => { this.pointers.delete(e.pointerId); this.gesture = true; }, options);
    canvas.addEventListener('keydown', e => {
      if (e.key === '+' || e.key === '=') this.zoom(0.85);
      else if (e.key === '-') this.zoom(1.15);
      else if (e.key.toLowerCase() === 'r') this.reset();
      else return;
      e.preventDefault();
    }, options);
    canvas.addEventListener('webglcontextlost', e => {
      e.preventDefault();
      onUnavailable();
    }, options);
    document.addEventListener('visibilitychange', this.requestRender, options);
    this.observer = new ResizeObserver(() => this.resize());
    this.observer.observe(host);
    this.resize();
  }

  protected material(color: number, metalness = 0, roughness = 0.65): THREE.MeshStandardMaterial {
    const material = new THREE.MeshStandardMaterial({ color, metalness, roughness });
    this.materials.add(material);
    return material;
  }

  protected mesh(geometry: THREE.BufferGeometry, material: THREE.Material, x: number, y: number, z: number, parent: THREE.Object3D = this.world): THREE.Mesh {
    this.geometries.add(geometry);
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(x, y, z);
    parent.add(mesh);
    return mesh;
  }

  protected fretX(fret: number): number {
    return -6 + 24 * (1 - Math.pow(2, -fret / 12));
  }

  protected noteX(fret: number): number {
    return fret === 0 ? -6.45 : (this.fretX(fret - 1) + this.fretX(fret)) / 2;
  }

  protected stringZ(string: number): number {
    return (string - 2.5) * 0.4;
  }

  /** Builds the visible instrument and its pick targets; subclasses may replace it. */
  protected buildScene(): void {
    this.buildNeck();
    this.buildTargets(12);
  }

  protected buildTargets(lastFret: number): void {
    for (let s = 0; s < 6; s++) {
      for (let f = 0; f <= lastFret; f++) {
        const width = f === 0 ? 0.7 : this.fretX(f) - this.fretX(f - 1);
        const targetMaterial = new THREE.MeshBasicMaterial({ visible: false });
        this.materials.add(targetMaterial);
        const target = this.mesh(new THREE.BoxGeometry(width, 0.35, 0.39), targetMaterial, this.noteX(f), 0.3, this.stringZ(s));
        target.userData = { string: s, fret: f };
        this.targets.push(target);
      }
    }
  }

  private buildNeck(): void {
    const wood = this.material(0x34251e);
    const back = this.material(0x76513a);
    const binding = this.material(0xc5ab82);
    const metal = this.material(0xb7b4aa, 0.78, 0.23);
    const pearl = this.material(0xd8cdb5, 0.2, 0.35);
    this.mesh(new THREE.BoxGeometry(12.8, 0.42, 2.62), back, 0, -0.35, 0);
    this.mesh(new THREE.BoxGeometry(12.8, 0.22, 2.58), wood, 0, -0.04, 0);
    for (const z of [-1.3, 1.3]) {
      this.mesh(new THREE.BoxGeometry(12.8, 0.065, 0.035), binding, 0, 0.06, z);
    }
    // Fine, deterministic grain made from geometry, not downloaded textures.
    const grain = this.material(0x493127);
    for (let i = 0; i < 28; i++) {
      const line = this.mesh(new THREE.BoxGeometry(12.7, 0.004, 0.008 + (i % 3) * 0.004), grain, 0, 0.073, -1.25 + i * 0.09);
      line.rotation.y = Math.sin(i * 7.1) * 0.002;
    }
    this.mesh(new THREE.BoxGeometry(0.11, 0.18, 2.6), pearl, -6, 0.13, 0);
    for (let f = 1; f <= 12; f++) {
      const wire = this.mesh(new THREE.CylinderGeometry(0.032, 0.032, 2.57, 8), metal, this.fretX(f), 0.12, 0);
      wire.rotation.x = Math.PI / 2;
      this.label(String(f), this.noteX(f), 0.02, -1.66, 0.36, 0xa99f91);
      if ([3, 5, 7, 9, 12].includes(f)) {
        for (const z of f === 12 ? [-0.48, 0.48] : [0]) {
          this.mesh(new THREE.CylinderGeometry(0.105, 0.105, 0.01, 24), pearl, this.noteX(f), 0.079, z);
        }
      }
    }
    for (let s = 0; s < 6; s++) {
      const radius = 0.009 + s * 0.0025;
      const wire = this.mesh(new THREE.CylinderGeometry(radius, radius, 13.3, 10), metal, -0.05, 0.21, this.stringZ(s));
      wire.rotation.z = Math.PI / 2;
    }
  }

  protected label(text: string, x: number, y: number, z: number, size: number, color = 0x211a12, parent: THREE.Object3D = this.world): THREE.Sprite {
    const cacheKey = `${text}:${color}`;
    let texture = this.textures.get(cacheKey);
    if (!texture) {
      const canvas = document.createElement('canvas');
      canvas.width = 128;
      canvas.height = 96;
      const ctx = canvas.getContext('2d')!;
      ctx.fillStyle = `#${color.toString(16).padStart(6, '0')}`;
      ctx.font = '600 54px system-ui';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(text, 64, 49);
      texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      this.textures.set(cacheKey, texture);
    }
    const material = new THREE.SpriteMaterial({ map: texture, depthTest: false });
    this.materials.add(material);
    const sprite = new THREE.Sprite(material);
    sprite.position.set(x, y, z);
    sprite.scale.set(size * 1.33, size, 1);
    parent.add(sprite);
    return sprite;
  }

  /** Mirrors the world for left-handed players, retaining the original neck materials. */
  protected applyLook(look: GuitarLook): void {
    const mirror = look.hand === 'left' ? -1 : 1;
    if (mirror !== this.mirror) {
      this.mirror = mirror;
      this.world.scale.x = mirror;
      // Mirror the current view in place so the neck flips without jumping to another angle.
      this.camera.position.x *= -1;
      this.controls.target.x *= -1;
      const { minAzimuthAngle, maxAzimuthAngle } = this.controls;
      this.controls.minAzimuthAngle = -maxAzimuthAngle;
      this.controls.maxAzimuthAngle = -minAzimuthAngle;
      this.controls.update();
    }
    this.requestRender();
  }

  /** Points the raycaster at a client position; split views override this to pick the right camera. */
  protected setPickRay(clientX: number, clientY: number): boolean {
    const rect = this.renderer.domElement.getBoundingClientRect();
    if (!rect.width || !rect.height) return false;
    this.raycaster.setFromCamera(new THREE.Vector2(
      (clientX - rect.left) / rect.width * 2 - 1,
      -(clientY - rect.top) / rect.height * 2 + 1,
    ), this.camera);
    return true;
  }

  update(state: NeckState): void {
    this.markers.traverse(object => {
      const drawable = object as THREE.Mesh;
      if (drawable.geometry) { drawable.geometry.dispose(); this.geometries.delete(drawable.geometry); }
      const material = (object as THREE.Sprite).material;
      if (material && !Array.isArray(material)) { material.dispose(); this.materials.delete(material); }
    });
    this.markers.clear();
    const scaleMode = Array.isArray(state.scalePositions);
    for (let s = 0; s < 6; s++) {
      const fret = state.frets[s];
      this.label(state.stringLabels?.[s] ?? state.tuning[s].note, -7.0, 0.2, this.stringZ(s), 0.33, 0xc0b7a9, this.markers);
      if (!scaleMode && fret === null) this.label('×', -6.45, 0.23, this.stringZ(s), 0.33, 0x9d9286, this.markers);
      for (let f = 0; f <= 12; f++) {
        const midi = state.tuning[s].midi + f;
        const pc = ((midi % 12) + 12) % 12;
        const live = state.liveMidi === midi;
        const scalePosition = state.scalePositions?.find(p => p.stringIndex === s && p.fret === f);
        // Decide whether to mark this position and how to color it.
        let show = live;
        let color = 0x89d7bc; // live = green
        if (!live) {
          if (scaleMode) {
            if (scalePosition) {
              show = true;
              color = scalePosition.active ? 0x89d7bc : scalePosition.role === 'root' ? 0xefb56d
                : scalePosition.role === 'blue' ? 0x9ec5e8 : 0xf0dfc6;
            }
          } else if (f === fret) {
            show = true;
            color = NOTE_NAMES[pc] === state.root ? 0xefb56d : 0xf0dfc6; // root amber, voicing cream
          }
        }
        if (!show) continue;
        const note = NOTE_NAMES[pc];
        const material = this.material(color, 0.15, 0.35);
        const geometry = new THREE.CylinderGeometry(0.175, 0.175, 0.07, 24);
        this.geometries.add(geometry);
        const marker = new THREE.Mesh(geometry, material);
        marker.position.set(this.noteX(f), 0.26, this.stringZ(s));
        marker.userData = { stringIndex: s, fret: f };
        this.markers.add(marker);
        if (scalePosition?.target) {
          const ring = new THREE.Mesh(new THREE.RingGeometry(0.20, 0.24, 24), new THREE.MeshBasicMaterial({ color: 0x9ec5e8, side: THREE.DoubleSide }));
          this.geometries.add(ring.geometry);
          this.materials.add(ring.material);
          ring.rotation.x = -Math.PI / 2;
          ring.position.set(this.noteX(f), 0.30, this.stringZ(s));
          this.markers.add(ring);
        }
        this.label(scalePosition?.label ?? note, this.noteX(f), 0.34, this.stringZ(s), 0.28, 0x211a12, this.markers);
      }
    }
    for (const next of state.upcoming ?? []) {
      if (!Number.isInteger(next.stringIndex) || next.stringIndex < 0 || next.stringIndex > 5 || !Number.isInteger(next.fret) || next.fret < 0 || next.fret > 12) continue;
      const x = this.noteX(next.fret), z = this.stringZ(next.stringIndex);
      const glow = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.03, 24),
        new THREE.MeshBasicMaterial({ color: 0x9dbfcd, transparent: true, opacity: 0.26, depthWrite: false }));
      glow.position.set(x, 0.24, z);
      this.geometries.add(glow.geometry); this.materials.add(glow.material);
      this.markers.add(glow);
      // A dashed ring reads as "coming up", distinct from solid current and scale-target markers.
      for (let d = 0; d < 10; d++) {
        const dash = new THREE.Mesh(new THREE.RingGeometry(0.19, 0.235, 6, 1, d * Math.PI / 5, Math.PI / 8),
          new THREE.MeshBasicMaterial({ color: 0x9dbfcd, side: THREE.DoubleSide }));
        dash.rotation.x = -Math.PI / 2;
        dash.position.set(x, 0.3, z);
        this.geometries.add(dash.geometry); this.materials.add(dash.material);
        this.markers.add(dash);
      }
      this.label(next.label, x, 0.34, z, 0.24, 0xcfe3ea, this.markers);
    }
    this.requestRender();
  }

  protected resize(): void {
    const { width, height } = this.host.getBoundingClientRect();
    if (!width || !height || this.disposed) return;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    // Frame the whole neck at any aspect ratio; zoom remains relative to home.
    this.camera.fov = THREE.MathUtils.radToDeg(2 * Math.atan(8.4 / (this.home.length() * this.camera.aspect)));
    this.camera.updateProjectionMatrix();
    this.requestRender();
  }

  setVisible(visible: boolean): void {
    this.visible = visible;
    if (!visible) { cancelAnimationFrame(this.frame); this.frame = 0; }
    else this.resize();
  }

  protected requestRender = (): void => {
    if (this.frame || this.disposed || !this.visible || document.hidden) return;
    this.frame = requestAnimationFrame(time => {
      this.frame = 0;
      if (!this.disposed && this.visible && !document.hidden) this.renderFrame(time);
    });
  };

  protected renderFrame(_time: number): void {
    this.renderer.render(this.scene, this.camera);
  }

  zoom(factor: number): void {
    const distance = this.camera.position.length();
    this.camera.position.multiplyScalar(Math.max(9, Math.min(25, distance * factor)) / distance);
    this.controls.update();
    this.requestRender();
  }

  reset(): void {
    this.camera.position.copy(this.home);
    this.camera.position.x *= this.mirror;
    this.controls.target.set(0, 0, 0);
    this.controls.update();
    this.requestRender();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    cancelAnimationFrame(this.frame);
    this.abort.abort();
    this.observer.disconnect();
    this.controls.dispose();
    this.geometries.forEach(geometry => geometry.dispose());
    this.materials.forEach(material => material.dispose());
    this.textures.forEach(texture => texture.dispose());
    this.scene.clear();
    this.renderer.dispose();
    this.renderer.forceContextLoss();
    this.renderer.domElement.remove();
  }
}
